values
  ('en-reading-A1-1', 'en', 'A1', 'A morning routine', 'Ana wakes up at seven. She drinks coffee, eats bread and walks to work.', 'Why does Ana walk to work?', '["It helps her start well","She dislikes breakfast","Her office is closed"]'::jsonb, 0, 1, true),
  ('en-reading-A1-2', 'en', 'A1', 'At the market', 'Leo goes to the market. He buys tomatoes, rice and two apples.', 'What does Leo do when an ingredient is expensive?', '["He abandons dinner","He chooses an alternative","He buys twice as much"]'::jsonb, 1, 2, true),
  ('en-reading-A1-3', 'en', 'A1', 'A rainy weekend', 'It is raining. Mia stays home, reads a book and calls her friend.', 'How does Mia react to the rain?', '["She finds other activities","She travels abroad","She waits outside"]'::jsonb, 0, 3, true),
  ('en-reading-A1-4', 'en', 'A1', 'The new colleague', 'Sam is new at work. Priya shows him the office and they have lunch together.', 'What helps Sam feel comfortable?', '["Working alone","Priya''s guidance","Skipping lunch"]'::jsonb, 1, 4, true),
  ('en-reading-A1-5', 'en', 'A1', 'Learning to cook', 'Nora wants to cook. She watches a video and makes soup.', 'What does Nora learn from the mistake?', '["To stop cooking","To correct and learn from it","To avoid videos"]'::jsonb, 1, 5, true),
  ('en-reading-A1-6', 'en', 'A1', 'Public transport', 'Ben takes the bus at eight. The bus is late, so he sends a message.', 'How does Ben manage the delay?', '["He communicates and plans","He cancels his job","He ignores the meeting"]'::jsonb, 0, 6, true),
  ('en-reading-A1-7', 'en', 'A1', 'A community garden', 'The neighbors grow vegetables together. They water the plants every day.', 'What is an additional benefit of the garden?', '["It strengthens relationships","It removes all work","It prevents people meeting"]'::jsonb, 0, 7, true),
  ('en-reading-A1-8', 'en', 'A1', 'Choosing a course', 'Lina wants to study English. She chooses an evening class near home.', 'Why does Lina choose the course?', '["It matches her needs","It has no classes","It is the farthest away"]'::jsonb, 0, 8, true),
  ('en-reading-A1-9', 'en', 'A1', 'A difficult conversation', 'Tom is upset. He talks calmly to his roommate about the noise.', 'What makes Tom''s approach effective?', '["He focuses on a solution","He shouts immediately","He avoids the issue"]'::jsonb, 0, 9, true),
  ('en-reading-A1-10', 'en', 'A1', 'A greener city', 'The city plants trees and builds cycle lanes. More people walk outside.', 'What happened after the redesign?', '["Visits increased","All shops closed","Walking was forbidden"]'::jsonb, 0, 10, true),
  ('en-reading-A2-1', 'en', 'A2', 'A morning routine', 'Ana usually wakes up at seven, but today she got up earlier because she has an important meeting. After breakfast, she walked to work.', 'Why does Ana walk to work?', '["It helps her start well","She dislikes breakfast","Her office is closed"]'::jsonb, 0, 11, true),
  ('en-reading-A2-2', 'en', 'A2', 'At the market', 'Leo went to the market to buy ingredients for dinner. Tomatoes were expensive, so he chose carrots instead and bought apples for dessert.', 'What does Leo do when an ingredient is expensive?', '["He abandons dinner","He chooses an alternative","He buys twice as much"]'::jsonb, 1, 12, true),
  ('en-reading-A2-3', 'en', 'A2', 'A rainy weekend', 'Mia planned to visit the park, but heavy rain changed her plans. She stayed home, finished a book and called a friend in the evening.', 'How does Mia react to the rain?', '["She finds other activities","She travels abroad","She waits outside"]'::jsonb, 0, 13, true),
  ('en-reading-A2-4', 'en', 'A2', 'The new colleague', 'Sam started his new job on Monday. Priya introduced him to the team, explained the daily routine and invited him to lunch.', 'What helps Sam feel comfortable?', '["Working alone","Priya''s guidance","Skipping lunch"]'::jsonb, 1, 14, true),
  ('en-reading-A2-5', 'en', 'A2', 'Learning to cook', 'Nora had never made soup before, so she followed a short video. She added too much salt, but potatoes helped improve the taste.', 'What does Nora learn from the mistake?', '["To stop cooking","To correct and learn from it","To avoid videos"]'::jsonb, 1, 15, true),
  ('en-reading-A2-6', 'en', 'A2', 'Public transport', 'Ben normally takes the eight o''clock bus. Today it arrived twenty minutes late, and he messaged his manager before the meeting started.', 'How does Ben manage the delay?', '["He communicates and plans","He cancels his job","He ignores the meeting"]'::jsonb, 0, 16, true),
  ('en-reading-A2-7', 'en', 'A2', 'A community garden', 'The neighbors transformed an empty lot into a small garden. Each family waters the plants on a different day and everyone shares the vegetables.', 'What is an additional benefit of the garden?', '["It strengthens relationships","It removes all work","It prevents people meeting"]'::jsonb, 0, 17, true),
  ('en-reading-A2-8', 'en', 'A2', 'Choosing a course', 'Lina compared three English courses. She chose the evening option because it fits her work schedule and includes conversation practice.', 'Why does Lina choose the course?', '["It matches her needs","It has no classes","It is the farthest away"]'::jsonb, 0, 18, true),
  ('en-reading-A2-9', 'en', 'A2', 'A difficult conversation', 'Tom could not sleep because his roommate played music late. The next morning, he explained the problem calmly and suggested quiet hours.', 'What makes Tom''s approach effective?', '["He focuses on a solution","He shouts immediately","He avoids the issue"]'::jsonb, 0, 19, true),
  ('en-reading-A2-10', 'en', 'A2', 'A greener city', 'The city replaced some parking spaces with trees and cycle lanes. At first, shop owners worried, but more pedestrians began visiting the area.', 'What happened after the redesign?', '["Visits increased","All shops closed","Walking was forbidden"]'::jsonb, 0, 20, true),
  ('en-reading-B1-1', 'en', 'B1', 'A morning routine', 'Ana protects the first hour of her morning from distractions. She prepares breakfast, reviews her priorities and walks to work, which helps her arrive calm and focused.', 'Why does Ana walk to work?', '["It helps her start well","She dislikes breakfast","Her office is closed"]'::jsonb, 0, 21, true),
  ('en-reading-B1-2', 'en', 'B1', 'At the market', 'Leo compares prices before choosing his ingredients. When he notices that tomatoes cost twice as much as usual, he adapts the recipe rather than exceeding his budget.', 'What does Leo do when an ingredient is expensive?', '["He abandons dinner","He chooses an alternative","He buys twice as much"]'::jsonb, 1, 22, true),
  ('en-reading-B1-3', 'en', 'B1', 'A rainy weekend', 'Although the weather ruined Mia''s outdoor plans, she decided not to waste the weekend. She caught up on her reading and had a long conversation with a friend who lives abroad.', 'How does Mia react to the rain?', '["She finds other activities","She travels abroad","She waits outside"]'::jsonb, 0, 23, true),
  ('en-reading-B1-4', 'en', 'B1', 'The new colleague', 'Starting a new job made Sam nervous, but Priya helped him settle in. By explaining unwritten routines and introducing him personally, she made the workplace feel less intimidating.', 'What helps Sam feel comfortable?', '["Working alone","Priya''s guidance","Skipping lunch"]'::jsonb, 1, 24, true),
  ('en-reading-B1-5', 'en', 'B1', 'Learning to cook', 'Nora learns best by experimenting. When her first soup becomes too salty, she researches possible solutions and discovers that adding potatoes can absorb some of the excess.', 'What does Nora learn from the mistake?', '["To stop cooking","To correct and learn from it","To avoid videos"]'::jsonb, 1, 25, true),
  ('en-reading-B1-6', 'en', 'B1', 'Public transport', 'Because the bus service has become unreliable, Ben now leaves home earlier and checks live updates. Informing his manager promptly also prevents a delay from becoming a misunderstanding.', 'How does Ben manage the delay?', '["He communicates and plans","He cancels his job","He ignores the meeting"]'::jsonb, 0, 26, true),
  ('en-reading-B1-7', 'en', 'B1', 'A community garden', 'The community garden provides more than fresh food. People who rarely spoke before now exchange advice, organize weekend tasks and make decisions about their shared space.', 'What is an additional benefit of the garden?', '["It strengthens relationships","It removes all work","It prevents people meeting"]'::jsonb, 0, 27, true),
  ('en-reading-B1-8', 'en', 'B1', 'Choosing a course', 'Price mattered to Lina, but it was not her only criterion. She selected a course with flexible hours, small groups and frequent speaking activities because these features matched her goals.', 'Why does Lina choose the course?', '["It matches her needs","It has no classes","It is the farthest away"]'::jsonb, 0, 28, true),
  ('en-reading-B1-9', 'en', 'B1', 'A difficult conversation', 'Instead of complaining while he was angry, Tom waited until morning. He described how the noise affected him and proposed a practical agreement that respected both people''s routines.', 'What makes Tom''s approach effective?', '["He focuses on a solution","He shouts immediately","He avoids the issue"]'::jsonb, 0, 29, true),
  ('en-reading-B1-10', 'en', 'B1', 'A greener city', 'Local businesses initially feared that reducing parking would discourage customers. After six months, however, pedestrian traffic increased and people spent more time in the redesigned streets.', 'What happened after the redesign?', '["Visits increased","All shops closed","Walking was forbidden"]'::jsonb, 0, 30, true),
  ('en-reading-B2-1', 'en', 'B2', 'A morning routine', 'Although Ana''s schedule is demanding, she avoids beginning the day in a rush. Her deliberate routine—breakfast, planning and a quiet walk—creates a sense of control that improves her concentration.', 'Why does Ana walk to work?', '["It helps her start well","She dislikes breakfast","Her office is closed"]'::jsonb, 0, 31, true),
  ('en-reading-B2-2', 'en', 'B2', 'At the market', 'Rising food prices have made Leo more flexible in the kitchen. Instead of following recipes rigidly, he substitutes seasonal ingredients, a habit that reduces both his expenses and food waste.', 'What does Leo do when an ingredient is expensive?', '["He abandons dinner","He chooses an alternative","He buys twice as much"]'::jsonb, 1, 32, true),
  ('en-reading-B2-3', 'en', 'B2', 'A rainy weekend', 'The storm forced Mia to abandon her carefully planned weekend, yet the slower pace proved unexpectedly restorative. By evening, she realized that an unplanned day could be just as satisfying as a busy one.', 'How does Mia react to the rain?', '["She finds other activities","She travels abroad","She waits outside"]'::jsonb, 0, 33, true),
  ('en-reading-B2-4', 'en', 'B2', 'The new colleague', 'Sam''s technical training covered his formal responsibilities, but Priya''s informal guidance proved equally valuable. Her explanations of team habits allowed him to participate confidently without fearing minor social mistakes.', 'What helps Sam feel comfortable?', '["Working alone","Priya''s guidance","Skipping lunch"]'::jsonb, 1, 34, true),
  ('en-reading-B2-5', 'en', 'B2', 'Learning to cook', 'Rather than treating her oversalted soup as a failure, Nora regards it as useful feedback. The experience teaches her both a practical technique and a broader lesson: mistakes are often the fastest route to competence.', 'What does Nora learn from the mistake?', '["To stop cooking","To correct and learn from it","To avoid videos"]'::jsonb, 1, 35, true),
  ('en-reading-B2-6', 'en', 'B2', 'Public transport', 'The recurring delays have changed Ben''s view of punctuality. He cannot control public transport, but he can anticipate uncertainty, communicate early and avoid presenting predictable disruptions as unexpected excuses.', 'How does Ben manage the delay?', '["He communicates and plans","He cancels his job","He ignores the meeting"]'::jsonb, 0, 36, true),
  ('en-reading-B2-7', 'en', 'B2', 'A community garden', 'What began as an environmental project has quietly strengthened the neighborhood''s social fabric. Shared responsibility creates repeated opportunities for cooperation, turning casual proximity into genuine community.', 'What is an additional benefit of the garden?', '["It strengthens relationships","It removes all work","It prevents people meeting"]'::jsonb, 0, 37, true),
  ('en-reading-B2-8', 'en', 'B2', 'Choosing a course', 'Lina resisted choosing the cheapest or most prestigious course automatically. By evaluating teaching style, schedule and opportunities for active practice, she treated the decision as an investment tailored to her actual needs.', 'Why does Lina choose the course?', '["It matches her needs","It has no classes","It is the farthest away"]'::jsonb, 0, 38, true),
  ('en-reading-B2-9', 'en', 'B2', 'A difficult conversation', 'Tom framed the discussion around impact rather than blame. This choice reduced defensiveness and shifted the conversation from deciding who was wrong to negotiating a solution they could both sustain.', 'What makes Tom''s approach effective?', '["He focuses on a solution","He shouts immediately","He avoids the issue"]'::jsonb, 0, 39, true),
  ('en-reading-B2-10', 'en', 'B2', 'A greener city', 'The project illustrates how intuitive predictions can conflict with observed behavior. While opponents equated car access with commercial success, the evidence suggests that attractive public space can generate longer visits and stronger local trade.', 'What happened after the redesign?', '["Visits increased","All shops closed","Walking was forbidden"]'::jsonb, 0, 40, true),
  ('es-reading-A1-1', 'es', 'A1', 'Una rutina matutina', 'Ana se despierta a las siete. Bebe café, come pan y camina al trabajo.', '¿Por qué camina Ana al trabajo?', '["Le ayuda a empezar bien","No le gusta desayunar","La oficina está cerrada"]'::jsonb, 0, 1, true),
  ('es-reading-A1-2', 'es', 'A1', 'En el mercado', 'Leo va al mercado. Compra tomates, arroz y dos manzanas.', '¿Qué hace Leo si un ingrediente es caro?', '["Abandona la cena","Elige una alternativa","Compra el doble"]'::jsonb, 1, 2, true),
  ('es-reading-A1-3', 'es', 'A1', 'Un fin de semana lluvioso', 'Llueve. Mia se queda en casa, lee un libro y llama a su amiga.', '¿Cómo reacciona Mia a la lluvia?', '["Busca otras actividades","Viaja al extranjero","Espera fuera"]'::jsonb, 0, 3, true),
  ('es-reading-A1-4', 'es', 'A1', 'El nuevo compañero', 'Sam es nuevo en el trabajo. Priya le muestra la oficina y almuerzan juntos.', '¿Qué ayuda a Sam a sentirse cómodo?', '["Trabajar solo","La orientación de Priya","No almorzar"]'::jsonb, 1, 4, true),
  ('es-reading-A1-5', 'es', 'A1', 'Aprender a cocinar', 'Nora quiere cocinar. Mira un video y prepara sopa.', '¿Qué aprende Nora del error?', '["A dejar de cocinar","A corregir y aprender","A evitar videos"]'::jsonb, 1, 5, true),
  ('es-reading-A1-6', 'es', 'A1', 'El transporte público', 'Ben toma el autobús a las ocho. Llega tarde y envía un mensaje.', '¿Cómo gestiona Ben el retraso?', '["Comunica y planifica","Deja su trabajo","Ignora la reunión"]'::jsonb, 0, 6, true),
  ('es-reading-A1-7', 'es', 'A1', 'Un huerto comunitario', 'Los vecinos cultivan verduras. Riegan las plantas todos los días.', '¿Qué beneficio adicional tiene el huerto?', '["Fortalece las relaciones","Elimina todo el trabajo","Evita los encuentros"]'::jsonb, 0, 7, true),
  ('es-reading-A1-8', 'es', 'A1', 'Elegir un curso', 'Lina quiere estudiar inglés. Elige una clase nocturna cerca de casa.', '¿Por qué elige Lina ese curso?', '["Se adapta a sus necesidades","No tiene clases","Es el más lejano"]'::jsonb, 0, 8, true),
  ('es-reading-A1-9', 'es', 'A1', 'Una conversación difícil', 'Tom está molesto. Habla con calma con su compañero sobre el ruido.', '¿Por qué funciona su estrategia?', '["Busca una solución","Grita inmediatamente","Evita el problema"]'::jsonb, 0, 9, true),
  ('es-reading-A1-10', 'es', 'A1', 'Una ciudad más verde', 'La ciudad planta árboles y construye ciclovías. Más personas caminan.', '¿Qué ocurrió después del cambio?', '["Aumentaron las visitas","Cerraron todos los negocios","Se prohibió caminar"]'::jsonb, 0, 10, true),
  ('es-reading-A2-1', 'es', 'A2', 'Una rutina matutina', 'Ana suele despertarse a las siete, pero hoy se levantó antes porque tiene una reunión importante. Después del desayuno, caminó al trabajo.', '¿Por qué camina Ana al trabajo?', '["Le ayuda a empezar bien","No le gusta desayunar","La oficina está cerrada"]'::jsonb, 0, 11, true),
  ('es-reading-A2-2', 'es', 'A2', 'En el mercado', 'Leo fue al mercado para comprar la cena. Los tomates estaban caros, así que eligió zanahorias y compró manzanas de postre.', '¿Qué hace Leo si un ingrediente es caro?', '["Abandona la cena","Elige una alternativa","Compra el doble"]'::jsonb, 1, 12, true),
  ('es-reading-A2-3', 'es', 'A2', 'Un fin de semana lluvioso', 'Mia pensaba ir al parque, pero la lluvia cambió sus planes. Se quedó en casa, terminó un libro y llamó a una amiga.', '¿Cómo reacciona Mia a la lluvia?', '["Busca otras actividades","Viaja al extranjero","Espera fuera"]'::jsonb, 0, 13, true),
  ('es-reading-A2-4', 'es', 'A2', 'El nuevo compañero', 'Sam empezó su nuevo trabajo el lunes. Priya lo presentó al equipo, explicó la rutina y lo invitó a almorzar.', '¿Qué ayuda a Sam a sentirse cómodo?', '["Trabajar solo","La orientación de Priya","No almorzar"]'::jsonb, 1, 14, true),
  ('es-reading-A2-5', 'es', 'A2', 'Aprender a cocinar', 'Nora nunca había preparado sopa. Siguió un video y puso demasiada sal, pero unas patatas mejoraron el sabor.', '¿Qué aprende Nora del error?', '["A dejar de cocinar","A corregir y aprender","A evitar videos"]'::jsonb, 1, 15, true),
  ('es-reading-A2-6', 'es', 'A2', 'El transporte público', 'Ben normalmente toma el autobús de las ocho. Hoy llegó veinte minutos tarde y avisó a su gerente antes de la reunión.', '¿Cómo gestiona Ben el retraso?', '["Comunica y planifica","Deja su trabajo","Ignora la reunión"]'::jsonb, 0, 16, true),
  ('es-reading-A2-7', 'es', 'A2', 'Un huerto comunitario', 'Los vecinos convirtieron un terreno vacío en un huerto. Cada familia riega un día diferente y todos comparten las verduras.', '¿Qué beneficio adicional tiene el huerto?', '["Fortalece las relaciones","Elimina todo el trabajo","Evita los encuentros"]'::jsonb, 0, 17, true),
  ('es-reading-A2-8', 'es', 'A2', 'Elegir un curso', 'Lina comparó tres cursos. Eligió el nocturno porque combina con su trabajo e incluye práctica de conversación.', '¿Por qué elige Lina ese curso?', '["Se adapta a sus necesidades","No tiene clases","Es el más lejano"]'::jsonb, 0, 18, true),
  ('es-reading-A2-9', 'es', 'A2', 'Una conversación difícil', 'Tom no pudo dormir por la música. Por la mañana explicó el problema y propuso horas de silencio.', '¿Por qué funciona su estrategia?', '["Busca una solución","Grita inmediatamente","Evita el problema"]'::jsonb, 0, 19, true),
  ('es-reading-A2-10', 'es', 'A2', 'Una ciudad más verde', 'La ciudad cambió aparcamientos por árboles y ciclovías. Los comercios se preocuparon, pero llegaron más peatones.', '¿Qué ocurrió después del cambio?', '["Aumentaron las visitas","Cerraron todos los negocios","Se prohibió caminar"]'::jsonb, 0, 20, true),
  ('es-reading-B1-1', 'es', 'B1', 'Una rutina matutina', 'Ana protege la primera hora de la mañana de las distracciones. Desayuna, revisa sus prioridades y camina al trabajo para llegar tranquila y concentrada.', '¿Por qué camina Ana al trabajo?', '["Le ayuda a empezar bien","No le gusta desayunar","La oficina está cerrada"]'::jsonb, 0, 21, true),
  ('es-reading-B1-2', 'es', 'B1', 'En el mercado', 'Leo compara los precios antes de elegir. Cuando descubre que los tomates cuestan el doble de lo habitual, adapta la receta para no superar su presupuesto.', '¿Qué hace Leo si un ingrediente es caro?', '["Abandona la cena","Elige una alternativa","Compra el doble"]'::jsonb, 1, 22, true),
  ('es-reading-B1-3', 'es', 'B1', 'Un fin de semana lluvioso', 'Aunque el clima arruinó sus planes, Mia decidió aprovechar el fin de semana. Terminó sus lecturas y conversó mucho tiempo con una amiga que vive en otro país.', '¿Cómo reacciona Mia a la lluvia?', '["Busca otras actividades","Viaja al extranjero","Espera fuera"]'::jsonb, 0, 23, true),
  ('es-reading-B1-4', 'es', 'B1', 'El nuevo compañero', 'Empezar un nuevo empleo puso nervioso a Sam, pero Priya lo ayudó a adaptarse. Le explicó las costumbres del equipo y lo presentó personalmente.', '¿Qué ayuda a Sam a sentirse cómodo?', '["Trabajar solo","La orientación de Priya","No almorzar"]'::jsonb, 1, 24, true),
  ('es-reading-B1-5', 'es', 'B1', 'Aprender a cocinar', 'Nora aprende experimentando. Cuando su primera sopa queda demasiado salada, investiga soluciones y descubre que las patatas absorben parte del exceso.', '¿Qué aprende Nora del error?', '["A dejar de cocinar","A corregir y aprender","A evitar videos"]'::jsonb, 1, 25, true),
  ('es-reading-B1-6', 'es', 'B1', 'El transporte público', 'Como el servicio se ha vuelto irregular, Ben sale antes y consulta la información en directo. Avisar rápidamente evita que el retraso se convierta en un malentendido.', '¿Cómo gestiona Ben el retraso?', '["Comunica y planifica","Deja su trabajo","Ignora la reunión"]'::jsonb, 0, 26, true),
  ('es-reading-B1-7', 'es', 'B1', 'Un huerto comunitario', 'El huerto ofrece más que alimentos frescos. Personas que casi no hablaban ahora intercambian consejos, organizan tareas y deciden juntas.', '¿Qué beneficio adicional tiene el huerto?', '["Fortalece las relaciones","Elimina todo el trabajo","Evita los encuentros"]'::jsonb, 0, 27, true),
  ('es-reading-B1-8', 'es', 'B1', 'Elegir un curso', 'El precio era importante, pero no fue el único criterio. Lina eligió horarios flexibles, grupos pequeños y actividades orales porque coincidían con sus objetivos.', '¿Por qué elige Lina ese curso?', '["Se adapta a sus necesidades","No tiene clases","Es el más lejano"]'::jsonb, 0, 28, true),
  ('es-reading-B1-9', 'es', 'B1', 'Una conversación difícil', 'En lugar de quejarse enfadado, Tom esperó. Describió cómo le afectaba el ruido y propuso un acuerdo que respetaba ambas rutinas.', '¿Por qué funciona su estrategia?', '["Busca una solución","Grita inmediatamente","Evita el problema"]'::jsonb, 0, 29, true),
  ('es-reading-B1-10', 'es', 'B1', 'Una ciudad más verde', 'Los negocios temían que menos aparcamiento alejara a los clientes. Seis meses después, aumentaron los peatones y el tiempo que pasaban en la zona.', '¿Qué ocurrió después del cambio?', '["Aumentaron las visitas","Cerraron todos los negocios","Se prohibió caminar"]'::jsonb, 0, 30, true),
  ('es-reading-B2-1', 'es', 'B2', 'Una rutina matutina', 'Aunque su agenda es exigente, Ana evita comenzar el día con prisa. Su rutina deliberada —desayunar, planificar y caminar— le da una sensación de control que mejora su concentración.', '¿Por qué camina Ana al trabajo?', '["Le ayuda a empezar bien","No le gusta desayunar","La oficina está cerrada"]'::jsonb, 0, 31, true),
  ('es-reading-B2-2', 'es', 'B2', 'En el mercado', 'El aumento de los alimentos ha vuelto a Leo más flexible en la cocina. En lugar de seguir recetas rígidamente, sustituye ingredientes por productos de temporada y reduce gastos y desperdicios.', '¿Qué hace Leo si un ingrediente es caro?', '["Abandona la cena","Elige una alternativa","Compra el doble"]'::jsonb, 1, 32, true),
  ('es-reading-B2-3', 'es', 'B2', 'Un fin de semana lluvioso', 'La tormenta obligó a Mia a abandonar un fin de semana cuidadosamente planeado; sin embargo, el ritmo lento resultó inesperadamente reparador y tan satisfactorio como un día ocupado.', '¿Cómo reacciona Mia a la lluvia?', '["Busca otras actividades","Viaja al extranjero","Espera fuera"]'::jsonb, 0, 33, true),
  ('es-reading-B2-4', 'es', 'B2', 'El nuevo compañero', 'La formación técnica cubrió las responsabilidades formales de Sam, pero la orientación informal de Priya fue igual de valiosa: le permitió participar sin temer pequeños errores sociales.', '¿Qué ayuda a Sam a sentirse cómodo?', '["Trabajar solo","La orientación de Priya","No almorzar"]'::jsonb, 1, 34, true),
  ('es-reading-B2-5', 'es', 'B2', 'Aprender a cocinar', 'En vez de considerar la sopa salada un fracaso, Nora la interpreta como información útil. La experiencia le enseña una técnica y una lección: los errores suelen acelerar el aprendizaje.', '¿Qué aprende Nora del error?', '["A dejar de cocinar","A corregir y aprender","A evitar videos"]'::jsonb, 1, 35, true),
  ('es-reading-B2-6', 'es', 'B2', 'El transporte público', 'Los retrasos han cambiado la visión de Ben sobre la puntualidad. No controla el transporte, pero puede anticipar la incertidumbre, comunicarla y no presentar problemas previsibles como excusas inesperadas.', '¿Cómo gestiona Ben el retraso?', '["Comunica y planifica","Deja su trabajo","Ignora la reunión"]'::jsonb, 0, 36, true),
  ('es-reading-B2-7', 'es', 'B2', 'Un huerto comunitario', 'Lo que empezó como proyecto ambiental ha fortalecido el tejido social del barrio. La responsabilidad compartida crea oportunidades de cooperación y transforma la proximidad en comunidad.', '¿Qué beneficio adicional tiene el huerto?', '["Fortalece las relaciones","Elimina todo el trabajo","Evita los encuentros"]'::jsonb, 0, 37, true),
  ('es-reading-B2-8', 'es', 'B2', 'Elegir un curso', 'Lina evitó escoger automáticamente el curso más barato o prestigioso. Evaluó el método, el horario y la práctica activa como una inversión adaptada a sus necesidades reales.', '¿Por qué elige Lina ese curso?', '["Se adapta a sus necesidades","No tiene clases","Es el más lejano"]'::jsonb, 0, 38, true),
  ('es-reading-B2-9', 'es', 'B2', 'Una conversación difícil', 'Tom planteó la conversación desde el impacto y no desde la culpa. Así redujo la actitud defensiva y transformó el conflicto en la búsqueda de una solución sostenible.', '¿Por qué funciona su estrategia?', '["Busca una solución","Grita inmediatamente","Evita el problema"]'::jsonb, 0, 39, true),
  ('es-reading-B2-10', 'es', 'B2', 'Una ciudad más verde', 'El proyecto muestra cómo las predicciones intuitivas pueden contradecir el comportamiento observado. Aunque se asociaba el coche con las ventas, los espacios atractivos generaron visitas más largas y más comercio.', '¿Qué ocurrió después del cambio?', '["Aumentaron las visitas","Cerraron todos los negocios","Se prohibió caminar"]'::jsonb, 0, 40, true),
  ('fr-reading-A1-1', 'fr', 'A1', 'Une routine matinale', 'Ana se réveille à sept heures. Elle boit du café, mange du pain et va au travail à pied.', 'Pourquoi Ana va-t-elle au travail à pied ?', '["Cela l''aide à bien commencer","Elle déteste déjeuner","Le bureau est fermé"]'::jsonb, 0, 1, true),
