  ('fr-reading-A2-5', 'fr', 'A2', 'Apprendre à cuisiner', 'Nora n''avait jamais fait de soupe. Elle a suivi une vidéo et mis trop de sel, mais des pommes de terre ont amélioré le goût.', 'Que comprend Nora grâce à son erreur ?', '["Qu''il faut arrêter","Qu''on peut corriger et apprendre","Qu''il faut éviter les vidéos"]'::jsonb, 1, 15, true),
  ('fr-reading-A2-6', 'fr', 'A2', 'Les transports publics', 'Ben prend normalement le bus de huit heures. Aujourd''hui, il est arrivé vingt minutes en retard et Ben a prévenu son responsable.', 'Comment Ben gère-t-il le retard ?', '["Il communique et anticipe","Il quitte son emploi","Il ignore la réunion"]'::jsonb, 0, 16, true),
  ('fr-reading-A2-7', 'fr', 'A2', 'Un jardin partagé', 'Les voisins ont transformé un terrain vide en jardin. Chaque famille arrose un jour différent et tous partagent les légumes.', 'Quel est l''autre avantage du jardin ?', '["Il renforce les liens","Il supprime tout travail","Il empêche les rencontres"]'::jsonb, 0, 17, true),
