  ('it-reading-B1-1', 'it', 'B1', 'Una routine mattutina', 'Ana protegge la prima ora della giornata dalle distrazioni. Fa colazione, controlla le priorità e cammina fino all''ufficio per arrivare calma e concentrata.', 'Perché Ana va al lavoro a piedi?', '["La aiuta a iniziare bene","Non ama la colazione","L''ufficio è chiuso"]'::jsonb, 0, 21, true),
  ('it-reading-B1-2', 'it', 'B1', 'Al mercato', 'Leo confronta i prezzi prima di scegliere. Quando nota che i pomodori costano il doppio, adatta la ricetta per rispettare il budget.', 'Cosa fa Leo se un ingrediente è caro?', '["Annulla la cena","Sceglie un''alternativa","Ne compra il doppio"]'::jsonb, 1, 22, true),
  ('it-reading-B1-3', 'it', 'B1', 'Un fine settimana piovoso', 'Anche se il tempo ha rovinato i suoi piani, Mia ha deciso di sfruttare il fine settimana. Ha terminato le letture e parlato a lungo con un''amica all''estero.', 'Come reagisce Mia alla pioggia?', '["Trova altre attività","Va all''estero","Aspetta fuori"]'::jsonb, 0, 23, true),
  ('it-reading-B1-4', 'it', 'B1', 'Il nuovo collega', 'Iniziare un nuovo lavoro rendeva Sam nervoso, ma Priya lo ha aiutato spiegando le abitudini informali e presentandolo personalmente.', 'Cosa aiuta Sam a sentirsi tranquillo?', '["Lavorare solo","La guida di Priya","Saltare il pranzo"]'::jsonb, 1, 24, true),
  ('it-reading-B1-5', 'it', 'B1', 'Imparare a cucinare', 'Nora impara sperimentando. Quando la zuppa è troppo salata, cerca soluzioni e scopre che le patate assorbono parte dell''eccesso.', 'Cosa impara Nora dall''errore?', '["A smettere di cucinare","A correggere e imparare","A evitare i video"]'::jsonb, 1, 25, true),
  ('it-reading-B1-6', 'it', 'B1', 'Il trasporto pubblico', 'Poiché il servizio è diventato irregolare, Ben esce prima e controlla gli aggiornamenti. Avvisare subito evita che un ritardo diventi un malinteso.', 'Come gestisce Ben il ritardo?', '["Comunica e pianifica","Lascia il lavoro","Ignora la riunione"]'::jsonb, 0, 26, true),
  ('it-reading-B1-7', 'it', 'B1', 'Un orto condiviso', 'L''orto offre più del cibo fresco. Persone che parlavano poco ora scambiano consigli, organizzano compiti e prendono decisioni insieme.', 'Qual è un altro vantaggio dell''orto?', '["Rafforza i rapporti","Elimina ogni lavoro","Impedisce gli incontri"]'::jsonb, 0, 27, true),
  ('it-reading-B1-8', 'it', 'B1', 'Scegliere un corso', 'Il prezzo contava, ma non era l''unico criterio. Lina ha scelto orari flessibili, gruppi piccoli e frequenti attività orali.', 'Perché Lina sceglie quel corso?', '["Corrisponde ai suoi bisogni","Non ha lezioni","È il più lontano"]'::jsonb, 0, 28, true),
  ('it-reading-B1-9', 'it', 'B1', 'Una conversazione difficile', 'Invece di lamentarsi mentre era arrabbiato, Tom ha aspettato. Ha descritto l''effetto del rumore e proposto un accordo rispettoso di entrambi.', 'Perché il suo approccio funziona?', '["Cerca una soluzione","Grida subito","Evita il problema"]'::jsonb, 0, 29, true),
  ('it-reading-B1-10', 'it', 'B1', 'Una città più verde', 'I commercianti temevano che meno parcheggi allontanassero i clienti. Dopo sei mesi, i pedoni e la durata delle visite erano aumentati.', 'Cosa è successo dopo il cambiamento?', '["Le visite sono aumentate","Tutti i negozi hanno chiuso","Camminare è stato vietato"]'::jsonb, 0, 30, true),
  ('it-reading-B2-1', 'it', 'B2', 'Una routine mattutina', 'Benché i suoi impegni siano intensi, Ana evita di iniziare di corsa. La sua routine deliberata le dà un senso di controllo che migliora la concentrazione.', 'Perché Ana va al lavoro a piedi?', '["La aiuta a iniziare bene","Non ama la colazione","L''ufficio è chiuso"]'::jsonb, 0, 31, true),
  ('it-reading-B2-2', 'it', 'B2', 'Al mercato', 'L''aumento dei prezzi ha reso Leo più flessibile in cucina. Invece di seguire rigidamente le ricette, usa prodotti stagionali, riducendo spese e sprechi.', 'Cosa fa Leo se un ingrediente è caro?', '["Annulla la cena","Sceglie un''alternativa","Ne compra il doppio"]'::jsonb, 1, 32, true),
  ('it-reading-B2-3', 'it', 'B2', 'Un fine settimana piovoso', 'Il temporale ha costretto Mia ad abbandonare un programma accurato; tuttavia, il ritmo più lento si è rivelato rigenerante e soddisfacente quanto una giornata piena.', 'Come reagisce Mia alla pioggia?', '["Trova altre attività","Va all''estero","Aspetta fuori"]'::jsonb, 0, 33, true),
  ('it-reading-B2-4', 'it', 'B2', 'Il nuovo collega', 'La formazione tecnica copriva i compiti formali di Sam, ma la guida informale di Priya era altrettanto preziosa: gli permetteva di partecipare senza temere piccoli errori sociali.', 'Cosa aiuta Sam a sentirsi tranquillo?', '["Lavorare solo","La guida di Priya","Saltare il pranzo"]'::jsonb, 1, 34, true),
  ('it-reading-B2-5', 'it', 'B2', 'Imparare a cucinare', 'Invece di considerare la zuppa salata un fallimento, Nora la interpreta come informazione utile. Impara una tecnica e capisce che gli errori spesso accelerano la competenza.', 'Cosa impara Nora dall''errore?', '["A smettere di cucinare","A correggere e imparare","A evitare i video"]'::jsonb, 1, 35, true),
  ('it-reading-B2-6', 'it', 'B2', 'Il trasporto pubblico', 'I ritardi ricorrenti hanno cambiato l''idea di puntualità di Ben. Non controlla il trasporto, ma può prevedere l''incertezza e non presentare un problema prevedibile come scusa.', 'Come gestisce Ben il ritardo?', '["Comunica e pianifica","Lascia il lavoro","Ignora la riunione"]'::jsonb, 0, 36, true),
  ('it-reading-B2-7', 'it', 'B2', 'Un orto condiviso', 'Il progetto ambientale ha rafforzato silenziosamente il tessuto sociale del quartiere. La responsabilità condivisa crea occasioni di cooperazione e trasforma la vicinanza in comunità.', 'Qual è un altro vantaggio dell''orto?', '["Rafforza i rapporti","Elimina ogni lavoro","Impedisce gli incontri"]'::jsonb, 0, 37, true),
  ('it-reading-B2-8', 'it', 'B2', 'Scegliere un corso', 'Lina ha evitato di scegliere automaticamente il corso meno caro o prestigioso. Ha valutato metodo, orari e pratica come un investimento adatto ai suoi bisogni reali.', 'Perché Lina sceglie quel corso?', '["Corrisponde ai suoi bisogni","Non ha lezioni","È il più lontano"]'::jsonb, 0, 38, true),
  ('it-reading-B2-9', 'it', 'B2', 'Una conversazione difficile', 'Tom ha impostato la discussione sull''impatto anziché sulla colpa. Così ha ridotto la difensiva e trasformato il conflitto nella ricerca di una soluzione sostenibile.', 'Perché il suo approccio funziona?', '["Cerca una soluzione","Grida subito","Evita il problema"]'::jsonb, 0, 39, true),
  ('it-reading-B2-10', 'it', 'B2', 'Una città più verde', 'Il progetto mostra come le previsioni intuitive possano contraddire i comportamenti osservati. Sebbene l''auto sembrasse essenziale, gli spazi piacevoli hanno favorito visite più lunghe e commercio locale.', 'Cosa è successo dopo il cambiamento?', '["Le visite sono aumentate","Tutti i negozi hanno chiuso","Camminare è stato vietato"]'::jsonb, 0, 40, true);

insert into public.grammar_lessons (
  id, language, level, title, explanation, example, question, options,
