)
values
  ('en-grammar-A1-1-1', 'en', 'A1', 'Verb to be · 1', 'Use am with I, is with he/she/it and are with you/we/they.', 'I am ready. They are at home.', 'I ___ Brazilian.', '["am","is","are"]'::jsonb, 0, 1, true),
  ('en-grammar-A1-1-2', 'en', 'A1', 'Verb to be · 2', 'Use am with I, is with he/she/it and are with you/we/they.', 'I am ready. They are at home.', 'She ___ a teacher.', '["are","is","am"]'::jsonb, 1, 2, true),
  ('en-grammar-A1-1-3', 'en', 'A1', 'Verb to be · 3', 'Use am with I, is with he/she/it and are with you/we/they.', 'I am ready. They are at home.', 'We ___ tired.', '["is","am","are"]'::jsonb, 2, 3, true),
  ('en-grammar-A1-1-4', 'en', 'A1', 'Verb to be · 4', 'Use am with I, is with he/she/it and are with you/we/they.', 'I am ready. They are at home.', 'The book ___ new.', '["is","are","am"]'::jsonb, 0, 4, true),
  ('en-grammar-A1-1-5', 'en', 'A1', 'Verb to be · 5', 'Use am with I, is with he/she/it and are with you/we/they.', 'I am ready. They are at home.', 'You ___ early.', '["am","are","is"]'::jsonb, 1, 5, true),
  ('en-grammar-A1-2-1', 'en', 'A1', 'Articles and plurals · 1', 'Use a before a consonant sound, an before a vowel sound, and add -s or -es for most plurals.', 'a book, an apple, two boxes', 'It is ___ orange.', '["a","an","two"]'::jsonb, 1, 6, true),
  ('en-grammar-A1-2-2', 'en', 'A1', 'Articles and plurals · 2', 'Use a before a consonant sound, an before a vowel sound, and add -s or -es for most plurals.', 'a book, an apple, two boxes', 'I have two ___.', '["watch","watches","watchs"]'::jsonb, 1, 7, true),
  ('en-grammar-A1-2-3', 'en', 'A1', 'Articles and plurals · 3', 'Use a before a consonant sound, an before a vowel sound, and add -s or -es for most plurals.', 'a book, an apple, two boxes', 'She is ___ doctor.', '["an","a","some"]'::jsonb, 1, 8, true),
  ('en-grammar-A1-2-4', 'en', 'A1', 'Articles and plurals · 4', 'Use a before a consonant sound, an before a vowel sound, and add -s or -es for most plurals.', 'a book, an apple, two boxes', 'Three ___ are here.', '["child","children","childs"]'::jsonb, 1, 9, true),
  ('en-grammar-A1-2-5', 'en', 'A1', 'Articles and plurals · 5', 'Use a before a consonant sound, an before a vowel sound, and add -s or -es for most plurals.', 'a book, an apple, two boxes', 'He wants ___ umbrella.', '["a","an","many"]'::jsonb, 1, 10, true),
  ('en-grammar-A2-3-1', 'en', 'A2', 'Simple present · 1', 'Use the base verb for routines; add -s or -es with he, she and it.', 'I work. She studies.', 'Tom ___ English daily.', '["study","studies","studying"]'::jsonb, 1, 11, true),
  ('en-grammar-A2-3-2', 'en', 'A2', 'Simple present · 2', 'Use the base verb for routines; add -s or -es with he, she and it.', 'I work. She studies.', 'They ___ at nine.', '["starts","start","starting"]'::jsonb, 1, 12, true),
  ('en-grammar-A2-3-3', 'en', 'A2', 'Simple present · 3', 'Use the base verb for routines; add -s or -es with he, she and it.', 'I work. She studies.', 'My bus ___ here.', '["stop","stops","stopping"]'::jsonb, 1, 13, true),
  ('en-grammar-A2-3-4', 'en', 'A2', 'Simple present · 4', 'Use the base verb for routines; add -s or -es with he, she and it.', 'I work. She studies.', 'I ___ coffee.', '["likes","like","liking"]'::jsonb, 1, 14, true),
  ('en-grammar-A2-3-5', 'en', 'A2', 'Simple present · 5', 'Use the base verb for routines; add -s or -es with he, she and it.', 'I work. She studies.', 'Ana ___ TV at night.', '["watch","watches","watchs"]'::jsonb, 1, 15, true),
  ('en-grammar-A2-4-1', 'en', 'A2', 'Past simple · 1', 'Use the past form for completed actions at a finished time.', 'We visited Rome last year.', 'I ___ her yesterday.', '["see","saw","seen"]'::jsonb, 1, 16, true),
  ('en-grammar-A2-4-2', 'en', 'A2', 'Past simple · 2', 'Use the past form for completed actions at a finished time.', 'We visited Rome last year.', 'They ___ late.', '["arrived","arrive","arriven"]'::jsonb, 0, 17, true),
  ('en-grammar-A2-4-3', 'en', 'A2', 'Past simple · 3', 'Use the past form for completed actions at a finished time.', 'We visited Rome last year.', 'He ___ breakfast.', '["didn''t ate","didn''t eat","not eat"]'::jsonb, 1, 18, true),
  ('en-grammar-A2-4-4', 'en', 'A2', 'Past simple · 4', 'Use the past form for completed actions at a finished time.', 'We visited Rome last year.', '___ you call me?', '["Did","Do","Were"]'::jsonb, 0, 19, true),
  ('en-grammar-A2-4-5', 'en', 'A2', 'Past simple · 5', 'Use the past form for completed actions at a finished time.', 'We visited Rome last year.', 'She ___ a new bag.', '["buyed","bought","buys"]'::jsonb, 1, 20, true),
  ('en-grammar-A2-5-1', 'en', 'A2', 'Future plans · 1', 'Use be going to for intentions and present continuous for arranged plans.', 'I''m going to study. We''re meeting at six.', 'I ___ visit my aunt.', '["am going to","going","will to"]'::jsonb, 0, 21, true),
  ('en-grammar-A2-5-2', 'en', 'A2', 'Future plans · 2', 'Use be going to for intentions and present continuous for arranged plans.', 'I''m going to study. We''re meeting at six.', 'We ___ at eight tomorrow.', '["meet","are meeting","met"]'::jsonb, 1, 22, true),
  ('en-grammar-A2-5-3', 'en', 'A2', 'Future plans · 3', 'Use be going to for intentions and present continuous for arranged plans.', 'I''m going to study. We''re meeting at six.', 'She is going ___ cook.', '["for","to","at"]'::jsonb, 1, 23, true),
  ('en-grammar-A2-5-4', 'en', 'A2', 'Future plans · 4', 'Use be going to for intentions and present continuous for arranged plans.', 'I''m going to study. We''re meeting at six.', 'They ___ flying on Friday.', '["is","are","be"]'::jsonb, 1, 24, true),
  ('en-grammar-A2-5-5', 'en', 'A2', 'Future plans · 5', 'Use be going to for intentions and present continuous for arranged plans.', 'I''m going to study. We''re meeting at six.', 'What are you ___ tonight?', '["do","doing","did"]'::jsonb, 1, 25, true),
  ('en-grammar-B1-6-1', 'en', 'B1', 'Present perfect · 1', 'Use have/has + past participle for experience or a past action connected to now.', 'I have visited London twice.', 'She ___ the report.', '["has finished","finished has","have finish"]'::jsonb, 0, 26, true),
  ('en-grammar-B1-6-2', 'en', 'B1', 'Present perfect · 2', 'Use have/has + past participle for experience or a past action connected to now.', 'I have visited London twice.', 'Have you ever ___ sushi?', '["eat","ate","eaten"]'::jsonb, 2, 27, true),
  ('en-grammar-B1-6-3', 'en', 'B1', 'Present perfect · 3', 'Use have/has + past participle for experience or a past action connected to now.', 'I have visited London twice.', 'We ___ him since May.', '["haven''t seen","didn''t saw","not see"]'::jsonb, 0, 28, true),
  ('en-grammar-B1-6-4', 'en', 'B1', 'Present perfect · 4', 'Use have/has + past participle for experience or a past action connected to now.', 'I have visited London twice.', 'He has ___ arrived.', '["yet","just","last"]'::jsonb, 1, 29, true),
  ('en-grammar-B1-6-5', 'en', 'B1', 'Present perfect · 5', 'Use have/has + past participle for experience or a past action connected to now.', 'I have visited London twice.', 'They haven''t called ___.', '["already","yet","ago"]'::jsonb, 1, 30, true),
  ('en-grammar-B1-7-1', 'en', 'B1', 'Relative clauses · 1', 'Use who for people, which for things and where for places to add information.', 'The woman who called is my manager.', 'The man ___ lives here is a doctor.', '["which","who","where"]'::jsonb, 1, 31, true),
  ('en-grammar-B1-7-2', 'en', 'B1', 'Relative clauses · 2', 'Use who for people, which for things and where for places to add information.', 'The woman who called is my manager.', 'This is the phone ___ I bought.', '["who","where","which"]'::jsonb, 2, 32, true),
  ('en-grammar-B1-7-3', 'en', 'B1', 'Relative clauses · 3', 'Use who for people, which for things and where for places to add information.', 'The woman who called is my manager.', 'That''s the café ___ we met.', '["where","who","whose"]'::jsonb, 0, 33, true),
  ('en-grammar-B1-7-4', 'en', 'B1', 'Relative clauses · 4', 'Use who for people, which for things and where for places to add information.', 'The woman who called is my manager.', 'I know a writer ___ books are famous.', '["whose","which","where"]'::jsonb, 0, 34, true),
  ('en-grammar-B1-7-5', 'en', 'B1', 'Relative clauses · 5', 'Use who for people, which for things and where for places to add information.', 'The woman who called is my manager.', 'The film, ___ was long, was excellent.', '["who","which","where"]'::jsonb, 1, 35, true),
  ('en-grammar-B1-8-1', 'en', 'B1', 'Modals and advice · 1', 'Use should for advice, must for strong obligation and might for possibility.', 'You should rest. It might rain.', 'You look ill. You ___ rest.', '["should","might not","would"]'::jsonb, 0, 36, true),
  ('en-grammar-B1-8-2', 'en', 'B1', 'Modals and advice · 2', 'Use should for advice, must for strong obligation and might for possibility.', 'You should rest. It might rain.', 'Passengers ___ show ID.', '["might","must","could"]'::jsonb, 1, 37, true),
  ('en-grammar-B1-8-3', 'en', 'B1', 'Modals and advice · 3', 'Use should for advice, must for strong obligation and might for possibility.', 'You should rest. It might rain.', 'It ___ rain later.', '["should to","might","must to"]'::jsonb, 1, 38, true),
  ('en-grammar-B1-8-4', 'en', 'B1', 'Modals and advice · 4', 'Use should for advice, must for strong obligation and might for possibility.', 'You should rest. It might rain.', 'You ___ smoke here.', '["mustn''t","don''t must","might"]'::jsonb, 0, 39, true),
  ('en-grammar-B1-8-5', 'en', 'B1', 'Modals and advice · 5', 'Use should for advice, must for strong obligation and might for possibility.', 'You should rest. It might rain.', '___ I borrow your pen?', '["Could","Must to","Should to"]'::jsonb, 0, 40, true),
  ('en-grammar-B2-9-1', 'en', 'B2', 'Conditionals · 1', 'Use conditionals to express facts, likely results, hypotheticals and unreal past outcomes.', 'If I had known, I would have helped.', 'If water reaches 100°C, it ___.', '["boils","would boil","boiled"]'::jsonb, 0, 41, true),
  ('en-grammar-B2-9-2', 'en', 'B2', 'Conditionals · 2', 'Use conditionals to express facts, likely results, hypotheticals and unreal past outcomes.', 'If I had known, I would have helped.', 'If it rains, we ___ inside.', '["stayed","will stay","would have stayed"]'::jsonb, 1, 42, true),
  ('en-grammar-B2-9-3', 'en', 'B2', 'Conditionals · 3', 'Use conditionals to express facts, likely results, hypotheticals and unreal past outcomes.', 'If I had known, I would have helped.', 'If I had more time, I ___ more.', '["travel","would travel","will travelled"]'::jsonb, 1, 43, true),
  ('en-grammar-B2-9-4', 'en', 'B2', 'Conditionals · 4', 'Use conditionals to express facts, likely results, hypotheticals and unreal past outcomes.', 'If I had known, I would have helped.', 'If she had called, I ___ answered.', '["would have","will have","had"]'::jsonb, 0, 44, true),
  ('en-grammar-B2-9-5', 'en', 'B2', 'Conditionals · 5', 'Use conditionals to express facts, likely results, hypotheticals and unreal past outcomes.', 'If I had known, I would have helped.', 'Unless you hurry, you ___ it.', '["miss","will miss","would missed"]'::jsonb, 1, 45, true),
  ('en-grammar-B2-10-1', 'en', 'B2', 'Reported speech and nuance · 1', 'Backshift tense when reporting past speech, and use reporting verbs to convey intention or attitude.', 'She said she had finished; he denied taking it.', '“I am busy.” She said she ___ busy.', '["is","was","has"]'::jsonb, 1, 46, true),
  ('en-grammar-B2-10-2', 'en', 'B2', 'Reported speech and nuance · 2', 'Backshift tense when reporting past speech, and use reporting verbs to convey intention or attitude.', 'She said she had finished; he denied taking it.', 'He ___ taking the money.', '["denied","denied to","said me not"]'::jsonb, 0, 47, true),
  ('en-grammar-B2-10-3', 'en', 'B2', 'Reported speech and nuance · 3', 'Backshift tense when reporting past speech, and use reporting verbs to convey intention or attitude.', 'She said she had finished; he denied taking it.', 'They suggested ___ earlier.', '["leave","leaving","to leaving"]'::jsonb, 1, 48, true),
  ('en-grammar-B2-10-4', 'en', 'B2', 'Reported speech and nuance · 4', 'Backshift tense when reporting past speech, and use reporting verbs to convey intention or attitude.', 'She said she had finished; he denied taking it.', 'She warned me ___ late.', '["not be","not to be","don''t be"]'::jsonb, 1, 49, true),
  ('en-grammar-B2-10-5', 'en', 'B2', 'Reported speech and nuance · 5', 'Backshift tense when reporting past speech, and use reporting verbs to convey intention or attitude.', 'She said she had finished; he denied taking it.', 'He claimed that he ___ the email.', '["had sent","has send","sent had"]'::jsonb, 0, 50, true),
  ('es-grammar-A1-1-1', 'es', 'A1', 'Ser y estar · 1', 'Ser expresa identidad o características; estar expresa estado o ubicación.', 'Soy brasileño. Estoy cansado.', 'Madrid ___ en España.', '["es","está","soy"]'::jsonb, 1, 1, true),
  ('es-grammar-A1-1-2', 'es', 'A1', 'Ser y estar · 2', 'Ser expresa identidad o características; estar expresa estado o ubicación.', 'Soy brasileño. Estoy cansado.', 'Nosotros ___ estudiantes.', '["somos","estamos","son"]'::jsonb, 0, 2, true),
  ('es-grammar-A1-1-3', 'es', 'A1', 'Ser y estar · 3', 'Ser expresa identidad o características; estar expresa estado o ubicación.', 'Soy brasileño. Estoy cansado.', 'Ella ___ contenta hoy.', '["es","está","soy"]'::jsonb, 1, 3, true),
  ('es-grammar-A1-1-4', 'es', 'A1', 'Ser y estar · 4', 'Ser expresa identidad o características; estar expresa estado o ubicación.', 'Soy brasileño. Estoy cansado.', 'El café ___ caliente.', '["está","eres","son"]'::jsonb, 0, 4, true),
  ('es-grammar-A1-1-5', 'es', 'A1', 'Ser y estar · 5', 'Ser expresa identidad o características; estar expresa estado o ubicación.', 'Soy brasileño. Estoy cansado.', 'Ellos ___ de México.', '["están","son","somos"]'::jsonb, 1, 5, true),
  ('es-grammar-A1-2-1', 'es', 'A1', 'Género y número · 1', 'Los sustantivos y adjetivos concuerdan generalmente en género y número.', 'un libro nuevo, unas casas blancas', 'Una mesa ___.', '["blanco","blanca","blancos"]'::jsonb, 1, 6, true),
  ('es-grammar-A1-2-2', 'es', 'A1', 'Género y número · 2', 'Los sustantivos y adjetivos concuerdan generalmente en género y número.', 'un libro nuevo, unas casas blancas', 'Dos coches ___.', '["rápidos","rápida","rápido"]'::jsonb, 0, 7, true),
  ('es-grammar-A1-2-3', 'es', 'A1', 'Género y número · 3', 'Los sustantivos y adjetivos concuerdan generalmente en género y número.', 'un libro nuevo, unas casas blancas', 'Las niñas son ___.', '["alto","altas","altos"]'::jsonb, 1, 8, true),
  ('es-grammar-A1-2-4', 'es', 'A1', 'Género y número · 4', 'Los sustantivos y adjetivos concuerdan generalmente en género y número.', 'un libro nuevo, unas casas blancas', 'Unos zapatos ___.', '["negra","negros","negro"]'::jsonb, 1, 9, true),
  ('es-grammar-A1-2-5', 'es', 'A1', 'Género y número · 5', 'Los sustantivos y adjetivos concuerdan generalmente en género y número.', 'un libro nuevo, unas casas blancas', 'El libro es ___.', '["interesante","interesantas","interesantes"]'::jsonb, 0, 10, true),
  ('es-grammar-A2-3-1', 'es', 'A2', 'Presente regular · 1', 'La terminación cambia según la persona y el grupo verbal -ar, -er o -ir.', 'Yo hablo. Nosotros aprendemos.', 'Nosotros ___ español.', '["estudiamos","estudian","estudia"]'::jsonb, 0, 11, true),
  ('es-grammar-A2-3-2', 'es', 'A2', 'Presente regular · 2', 'La terminación cambia según la persona y el grupo verbal -ar, -er o -ir.', 'Yo hablo. Nosotros aprendemos.', 'Ella ___ en Madrid.', '["vivo","vive","vivimos"]'::jsonb, 1, 12, true),
